import{_ as t,c as a,o,ae as i}from"./chunks/framework.Bi6zybwU.js";const c=JSON.parse('{"title":"Introduction- Getting Started with Ninja Tables","description":"Introduction- Getting Started with Ninja Tables","frontmatter":{"title":"Introduction- Getting Started with Ninja Tables","description":"Introduction- Getting Started with Ninja Tables"},"headers":[],"relativePath":"guide/getting-started/ninja-tables-introduction.md","filePath":"guide/getting-started/ninja-tables-introduction.md"}'),n={name:"guide/getting-started/ninja-tables-introduction.md"};function r(s,e,l,d,h,u){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="introduction-getting-started-with-ninja-tables" tabindex="-1">Introduction- Getting Started with Ninja Tables <a class="header-anchor" href="#introduction-getting-started-with-ninja-tables" aria-label="Permalink to &quot;Introduction- Getting Started with Ninja Tables&quot;">​</a></h1><p>Creating stunning responsive tables was always a struggle. And customizing those was an even bigger dispute. So here we are with all the solutions. It will give you the easiest way of making different types of WordPress tables within minutes and even without writing a single line of code! If you want to check out if this plugin fulfills your requirements for a WordPress table plugin, check out the <a href="https://ninjatables.com/features/" target="_blank" rel="noreferrer">feature page.</a></p><p><a href="https://youtu.be/GXqaXMVsnl8" target="_blank" rel="noreferrer">Watch Video</a> As soon as you install and activate Ninja Tables, you&#39;ll be welcomed with a short intro. You can start creating tables manually right from there or you can start practicing with an imported file. <img src="https://ninjatables.com/wp-content/uploads/2025/05/Welcome-to-Ninja-Tables-UI-1024x536.png" alt="Welcome to Ninja Tables UI"> Follow the documentations to get started. You can also go to the templates or the dmeo page for inspirations.</p><h2 id="_9-table-creation-options" tabindex="-1">9+ table creation options <a class="header-anchor" href="#_9-table-creation-options" aria-label="Permalink to &quot;9+ table creation options&quot;">​</a></h2><p>When you want to create a new table, Ninja Tables gives you multiple options. From the table creation options list, you can pick any type you want to start with.</p><ul><li>Default (create tables manually)</li><li>Drag &amp; Drop Table</li><li>Connect Fluent Forms</li><li>WP Posts</li><li>WooCommerce Table</li><li>Connect Google Sheets</li><li>Connect External CSV</li><li>Custom SQL Query <img src="https://ninjatables.com/wp-content/uploads/2025/05/Table-creation-option-UI-1024x536.webp" alt="New UI Table creation option"> These will be the primary options. But you can also choose to <strong>import a table CSV/JSON</strong> to create table. Or you can pick a <strong>template</strong> from Drag &amp; Drop mode or from the free table <a href="https://ninjatables.com/free-table-templates/" target="_blank" rel="noreferrer">templates</a> page.</li></ul><h2 id="drag-and-drop-table-builder" tabindex="-1">Drag and drop table builder <a class="header-anchor" href="#drag-and-drop-table-builder" aria-label="Permalink to &quot;Drag and drop table builder&quot;">​</a></h2><p>Ninja Tables offers the most accessible and most user-friendly interface for building tables by dragging and dropping the elements you need. Outstanding table elements and customization options make this drag-and-drop module a complete table builder plugin itself. <img src="https://ninjatables.com/wp-content/uploads/2023/07/Screenshot-2023-07-26-122526-1024x439.png" alt="Ninja Tables drag and drop"></p><h2 id="pre-built-table-template" tabindex="-1">Pre-built table template <a class="header-anchor" href="#pre-built-table-template" aria-label="Permalink to &quot;Pre-built table template&quot;">​</a></h2><p>Ninja Tables comes with a lot of pre-built templates. You can use many of those in the free version. Now you can create pricing tables, comparison tables, employee tables, or schedule tables the easiest way possible. <img src="https://ninjatables.com/wp-content/uploads/2022/10/Screenshot_7-1024x468.png" alt="Table Templates"></p><h2 id="responsive-table-plugin-in-wordpress" tabindex="-1">Responsive Table Plugin in WordPress <a class="header-anchor" href="#responsive-table-plugin-in-wordpress" aria-label="Permalink to &quot;Responsive Table Plugin in WordPress&quot;">​</a></h2><p>Make responsive tables with the Ninja Tables in the easiest way. WordPress tables’ search, pagination, sorting, and other features will also work on all devices. You have control over your table and what you want to show or not. <img src="https://ninjatables.com/wp-content/uploads/2022/07/Collapsed-Table-1-1024x537.png" alt="Collapsed Table"></p><h2 id="_100-table-design-customization-options" tabindex="-1">100+ Table design customization options <a class="header-anchor" href="#_100-table-design-customization-options" aria-label="Permalink to &quot;100+ Table design customization options&quot;">​</a></h2><p>Ninja Tables enables you to choose from a huge number of options for table design and customization.</p><ul><li>Single Line Cells</li><li>Fixed Layout</li><li>Hover Rows</li><li>Bordered Table</li><li>Striped Rows</li><li>Unlimited color scheme</li><li>Hide/show table title</li><li>Make the table sortable/filterable <img src="https://ninjatables.com/wp-content/uploads/2025/05/New-UI-table-design-tabs-1024x649.webp" alt="New UI table design tabs"> You can also make the table stackable to fit all screen types. And in the &quot;Other&quot; tab, you get to decide on table pagination, font settings, search bar positions, etc. Customize colors for the table from the &quot;Table Colors&quot; tab.</li></ul><h2 id="_3-most-popular-css-libraries-and-bootstrap-table" tabindex="-1">3 Most popular CSS libraries and Bootstrap table <a class="header-anchor" href="#_3-most-popular-css-libraries-and-bootstrap-table" aria-label="Permalink to &quot;3 Most popular CSS libraries and Bootstrap table&quot;">​</a></h2><p>Ninja Tables comes with the 3 most widespread CSS libraries, having multiple color schema and styles. Now you can choose from Bootstrap 3, Bootstrap 4, or Semantic UI Table Styles.</p><h2 id="fastest-wordpress-table-builder-with-ajax-and-legacy-rendering" tabindex="-1">Fastest WordPress table builder with Ajax and Legacy rendering <a class="header-anchor" href="#fastest-wordpress-table-builder-with-ajax-and-legacy-rendering" aria-label="Permalink to &quot;Fastest WordPress table builder with Ajax and Legacy rendering&quot;">​</a></h2><p>Ninja Tables operates from a single page on everything. VueJS and VueRouter as Single Page Applications (SPA) are used to develop the backend to make the experience smooth. Everything seems to be real-time, including making a table to set up the configuration, inserting entries, importing CSV files &amp; re-arranging columns. This process is very time-saving for the users. Combined with minimum load on JS &amp; CSS load, the front-end table loads faster. AJAX was configured for the front-end data load to manage thousands of table rows without impacting the page load time. <img src="https://ninjatables.com/wp-content/uploads/2025/05/New-UI-table-rendering-1024x461.webp" alt="New UI table rendering"></p><h2 id="free-templates" tabindex="-1">Free templates <a class="header-anchor" href="#free-templates" aria-label="Permalink to &quot;Free templates&quot;">​</a></h2><p>Save your time and choose a free <a href="https://ninjatables.com/free-table-templates/" target="_blank" rel="noreferrer">table template</a> from our collection. Ninja Tables has 40+ different table templates of multiple categories that you can download for free, import the table JSON, customize the table, and embed. <img src="https://ninjatables.com/wp-content/uploads/2024/05/template-categories-1024x811.webp" alt="template categories"> The instructions are all documented with each template file.</p><h2 id="simple-configuration-feature" tabindex="-1">Simple Configuration Feature <a class="header-anchor" href="#simple-configuration-feature" aria-label="Permalink to &quot;Simple Configuration Feature&quot;">​</a></h2><p>With our user-friendly column builder, table columns’ design and responsive breakpoints’ configuration make it easier to rearrange the columns. The text/HTML area and the data type, like Single Line Text Field, can be selected for every column.</p><h2 id="export-and-import-data" tabindex="-1">Export and Import Data <a class="header-anchor" href="#export-and-import-data" aria-label="Permalink to &quot;Export and Import Data&quot;">​</a></h2><p>You can retrieve the table data and apply them to some other program. The tables can be exported and saved in CSV/JSON file format. This way, the data will be kept safe &amp; transferable. CSV/JSON files can also be imported in the same method.</p><h2 id="import-tables-from-other-table-plugins" tabindex="-1">Import Tables From Other Table Plugins <a class="header-anchor" href="#import-tables-from-other-table-plugins" aria-label="Permalink to &quot;Import Tables From Other Table Plugins&quot;">​</a></h2><p>If you’re already using tables with added data from other plugins. No need to worry; for other table plugins like TablePress, you can simply import tables with data. <img src="https://ninjatables.com/wp-content/uploads/2025/06/New-UI-table-import-tools-and-settings-1024x536.webp" alt="New UI table import tools and settings"> ***The other table plugins section will only show up if you have them installed on your dashboard.</p><h2 id="woocommerce-integration" tabindex="-1">WooCommerce Integration <a class="header-anchor" href="#woocommerce-integration" aria-label="Permalink to &quot;WooCommerce Integration&quot;">​</a></h2><p>Ninja Tables offers a seamless solution for your WooCommerce product table needs. Thanks to the Pro integration of the plugin, crafting dynamic WooCommerce product tables is now a hassle-free task.  This functionality empowers you to design these tables effortlessly, enabling your site visitors to make multiple product purchases directly from a single page. The added benefit of customization options for the cart and checkout buttons further enhances the user experience. <img src="https://ninjatables.com/wp-content/uploads/2023/06/WooCommerce-product-table-1-925x1024.png" alt="WooCommerce product table"></p><h2 id="google-sheets-integration" tabindex="-1">Google Sheets Integration <a class="header-anchor" href="#google-sheets-integration" aria-label="Permalink to &quot;Google Sheets Integration&quot;">​</a></h2><p>The integration of your Google Sheets with Ninja Tables is undeniably one of its most impressive features. Furthermore, any modifications made to the data in your Google Sheets will be reflected in Ninja Tables through automatic updates. <img src="https://ninjatables.com/wp-content/uploads/2023/09/connect-google-sheets-to-ninja-tables-1024x536.png" alt="connect google sheets to ninja tables"></p><h2 id="fluent-forms-integration" tabindex="-1">Fluent Forms Integration <a class="header-anchor" href="#fluent-forms-integration" aria-label="Permalink to &quot;Fluent Forms Integration&quot;">​</a></h2><p>The integration of Fluent Forms with Ninja Tables is seamless, allowing you to effortlessly incorporate Fluent Forms entries into your tables. To gain a better understanding of this feature, feel free to view the instructional video below:</p><h3 id="fluent-forms-integration-video" tabindex="-1">Fluent Forms Integration(Video) <a class="header-anchor" href="#fluent-forms-integration-video" aria-label="Permalink to &quot;Fluent Forms Integration(Video)&quot;">​</a></h3><p><a href="https://youtu.be/uMVnTYnKWM4" target="_blank" rel="noreferrer">https://youtu.be/uMVnTYnKWM4</a></p><h2 id="ninja-tables-integration-with-ninja-charts" tabindex="-1">Ninja Tables Integration with Ninja Charts <a class="header-anchor" href="#ninja-tables-integration-with-ninja-charts" aria-label="Permalink to &quot;Ninja Tables Integration with Ninja Charts&quot;">​</a></h2><p>Ninja Charts, a data visualization plugin, has been seamlessly integrated with Ninja Tables, allowing you to utilize your table data for the creation and display of dynamic charts and graphs on your website.</p><h2 id="_24-7-fluent-support" tabindex="-1">24/7 Fluent Support <a class="header-anchor" href="#_24-7-fluent-support" aria-label="Permalink to &quot;24/7 Fluent Support&quot;">​</a></h2><p>Our exceptional support team is readily available to provide dedicated assistance for this remarkable WordPress table plugin, and this service comes at no cost to you! To access this support, simply generate a support ticket through the provided link. We eagerly anticipate your feature requests and stand ready to extend help for tailored table solutions. Feel free to create a support ticket to ensure the finest user experience.</p><h2 id="seo-optimized-tables" tabindex="-1">SEO-Optimized Tables <a class="header-anchor" href="#seo-optimized-tables" aria-label="Permalink to &quot;SEO-Optimized Tables&quot;">​</a></h2><p>While using an HTML table is a wise decision, it can become cumbersome when coding improvements are required. Fortunately, a variety of plugins are designed to simplify the creation of WordPress tables. Among these, Ninja Tables stands out as a premier table builder plugin within the WordPress repository. Its robust functionality empowers you to craft a diverse range of tables, all while maintaining excellent SEO compatibility.</p><h2 id="advanced-shortcode-for-customized-presentation" tabindex="-1">Advanced Shortcode for Customized Presentation <a class="header-anchor" href="#advanced-shortcode-for-customized-presentation" aria-label="Permalink to &quot;Advanced Shortcode for Customized Presentation&quot;">​</a></h2><p>The utilization of advanced shortcodes represents a valuable pro feature, particularly beneficial for developers. Within this feature, you can explore an extensive array of enhanced functionalities.  Ninja Tables provides a collection of highly useful shortcodes that grant you the flexibility to configure your tables to meet your exact requirements. This means you can present the same table on different pages or posts, each with a unique appearance and style.</p><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>That’s not all. When you are using Ninja Tables, you are free to create any kind of table for your website and customize them anyhow you want. The only limitation can be your creativity.  In the next few docs, we&#39;ll cover all the details of Ninja Tables <a href="https://ninjatables.com/docs-category/simple-mode/" target="_blank" rel="noreferrer">Simple Mode</a> and <a href="https://ninjatables.com/docs-category/advanced-mode/" target="_blank" rel="noreferrer">Advanced Mode</a>. If you have any other questions, feel free to comment below!</p>',45)])])}const b=t(n,[["render",r]]);export{c as __pageData,b as default};
